const headers={'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'same-origin'};
const json=(data,status=200,extra={})=>new Response(JSON.stringify(data),{status,headers:{...headers,...extra}});
const uid=()=>crypto.randomUUID();const enc=new TextEncoder();
const hex=b=>Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,'0')).join('');
async function digest(s){return hex(await crypto.subtle.digest('SHA-256',enc.encode(s)))}
async function passwordHash(password,salt){const key=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations:150000,hash:'SHA-256'},key,256);return btoa(String.fromCharCode(...new Uint8Array(bits)))}
function cookie(req,name){for(const p of (req.headers.get('cookie')||'').split(';')){const [k,...v]=p.trim().split('=');if(k===name)return v.join('=')}return ''}
function validOrigin(req){const o=req.headers.get('origin');return !o||o===new URL(req.url).origin}
async function currentUser(req,env){const token=cookie(req,'hazard_session');if(!token)return null;const hash=await digest(token);const row=await env.DB.prepare('SELECT u.id,u.username,u.display_name AS displayName,u.role,u.active,s.expires_at AS expiresAt FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=?').bind(hash).first();if(!row||!row.active||row.expiresAt<Date.now()){if(row)await env.DB.prepare('DELETE FROM sessions WHERE token_hash=?').bind(hash).run();return null}return{id:row.id,username:row.username,displayName:row.displayName,role:row.role,active:!!row.active}}
async function newSession(userId,env){const token=uid()+uid(),now=Date.now();await env.DB.prepare('INSERT INTO sessions(id,user_id,token_hash,expires_at,created_at) VALUES(?,?,?,?,?)').bind(uid(),userId,await digest(token),now+7*86400000,now).run();return`hazard_session=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=604800`}
const admin=u=>!!u&&u.role==='admin';const err=(m,s=400)=>json({error:m},s);const trim=(v,n)=>String(v??'').trim().slice(0,n);
async function api(req,env){const url=new URL(req.url),p=url.pathname.replace(/^\/api\/?/,'').split('/').filter(Boolean),m=req.method;
if(m!=='GET'&&!validOrigin(req))return err('Запрос отклонён: неверный источник',403);
if(m==='GET'&&p[0]==='auth'&&p[1]==='status'){const r=await env.DB.prepare('SELECT COUNT(*) AS n FROM users').first();return json({initialized:Number(r?.n||0)>0})}
if(m==='POST'&&p[0]==='auth'&&p[1]==='setup'){const v=await req.json(),c=await env.DB.prepare('SELECT COUNT(*) AS n FROM users').first();if(Number(c?.n||0)>0)return err('Первичная настройка уже выполнена',409);const setupKey=String(v.setupKey||'').trim(),boot=await env.DB.prepare('SELECT token_hash FROM bootstrap_tokens WHERE used=0 LIMIT 1').first();if(!boot||await digest(setupKey)!==boot.token_hash)return err('Неверный или уже использованный ключ первичной настройки',403);const username=trim(v.username,32),password=String(v.password||''),displayName=trim(v.displayName||username,80);if(!/^[a-zA-Z0-9._-]{3,32}$/.test(username)||password.length<12||password.length>128||!displayName)return err('Логин: 3–32 символа латиницей. Пароль: 12–128 символов.',400);const id=uid(),salt=uid(),now=Date.now();try{const hash=await passwordHash(password,salt);await env.DB.batch([env.DB.prepare("INSERT INTO users(id,username,display_name,password_hash,password_salt,role,active,created_at) SELECT ?,?,?,?,?,'admin',1,? WHERE EXISTS(SELECT 1 FROM bootstrap_tokens WHERE token_hash=? AND used=0) AND NOT EXISTS(SELECT 1 FROM users)").bind(id,username,displayName,hash,salt,now,boot.token_hash),env.DB.prepare('UPDATE bootstrap_tokens SET used=1 WHERE token_hash=? AND used=0 AND EXISTS(SELECT 1 FROM users WHERE id=?)').bind(boot.token_hash,id)]);}catch(e){console.error('ADMIN_SETUP_DB_ERROR',e);const msg=String(e);if(/UNIQUE constraint failed: users.username/i.test(msg))return err('Такой логин уже существует. Выберите другой.',409);return err('Ошибка базы при создании администратора: '+msg.slice(0,220),500);}const created=await env.DB.prepare('SELECT id FROM users WHERE id=?').bind(id).first();if(!created)return err('Администратор не создан: ключ уже использован или регистрация уже выполнена. Обновите страницу.',409);try{return json({user:{id,username,displayName,role:'admin'}},200,{'set-cookie':await newSession(id,env)})}catch(e){console.error('ADMIN_SETUP_SESSION_ERROR',e);return err('Учётная запись создана, но не удалось открыть сессию. Попробуйте войти с логином и паролем.',500)}}
if(m==='POST'&&p[0]==='auth'&&p[1]==='login'){const v=await req.json(),username=trim(v.username,32),password=String(v.password||''),ip=req.headers.get('CF-Connecting-IP')||'unknown',key=await digest(ip+'|'+username.toLowerCase()),now=Date.now();let lock=await env.DB.prepare('SELECT failures,window_started AS windowStarted,locked_until AS lockedUntil FROM login_attempts WHERE attempt_key=?').bind(key).first();if(lock?.lockedUntil>now)return err('Слишком много попыток. Попробуйте через 15 минут.',429);if(lock&&now-lock.windowStarted>15*60*1000){await env.DB.prepare('DELETE FROM login_attempts WHERE attempt_key=?').bind(key).run();lock=null}const row=await env.DB.prepare('SELECT id,username,display_name AS displayName,password_hash AS passwordHash,password_salt AS passwordSalt,role,active FROM users WHERE username=? COLLATE NOCASE').bind(username).first();const candidate=row?await passwordHash(password,row.passwordSalt):await passwordHash(password,'invalid-user-salt');if(!row||!row.active||candidate!==row.passwordHash){const failures=(lock?.failures||0)+1;await env.DB.prepare('INSERT INTO login_attempts(attempt_key,failures,window_started,locked_until) VALUES(?,?,?,?) ON CONFLICT(attempt_key) DO UPDATE SET failures=excluded.failures,locked_until=excluded.locked_until').bind(key,failures,lock?.windowStarted||now,failures>=7?now+15*60*1000:null).run();return err('Неверный логин или пароль',401)}await env.DB.prepare('DELETE FROM login_attempts WHERE attempt_key=?').bind(key).run();await env.DB.prepare('UPDATE users SET last_login=? WHERE id=?').bind(now,row.id).run();return json({user:{id:row.id,username:row.username,displayName:row.displayName,role:row.role}},200,{'set-cookie':await newSession(row.id,env)})}
if(m==='POST'&&p[0]==='auth'&&p[1]==='logout'){const token=cookie(req,'hazard_session');if(token)await env.DB.prepare('DELETE FROM sessions WHERE token_hash=?').bind(await digest(token)).run();return json({ok:true},200,{'set-cookie':'hazard_session=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0'})}
if(m==='GET'&&p[0]==='auth'&&p[1]==='me'){const u=await currentUser(req,env);return u?json({user:u}):err('Требуется вход',401)}
const user=await currentUser(req,env);if(!user)return err('Требуется вход',401);
if(p[0]==='admin'){if(!admin(user))return err('Недостаточно прав',403);
if(m==='GET'&&p[1]==='users'){const r=await env.DB.prepare('SELECT id,username,display_name AS displayName,role,active,created_at AS createdAt,last_login AS lastLogin FROM users ORDER BY created_at DESC').all();return json({users:r.results.map(x=>({...x,active:!!x.active}))})}
if(m==='POST'&&p[1]==='users'){const v=await req.json(),username=trim(v.username,32),password=String(v.password||''),displayName=trim(v.displayName||username,80),role=v.role==='admin'?'admin':'employee';if(!/^[a-zA-Z0-9._-]{3,32}$/.test(username)||password.length<12||password.length>128||!displayName)return err('Проверьте логин, имя и пароль (12+ символов)');const id=uid(),salt=uid();try{await env.DB.prepare('INSERT INTO users(id,username,display_name,password_hash,password_salt,role,active,created_at) VALUES(?,?,?,?,?,?,1,?)').bind(id,username,displayName,await passwordHash(password,salt),salt,role,Date.now()).run()}catch{return err('Такой логин уже существует',409)}return json({id,username,displayName,role})}
if(m==='PATCH'&&p[1]==='users'&&p[2]){const v=await req.json(),target=await env.DB.prepare('SELECT id,role,active FROM users WHERE id=?').bind(p[2]).first();if(!target)return err('Пользователь не найден',404);if(target.id===user.id&&(v.active===false||v.role==='employee'))return err('Нельзя отключить или понизить собственную учётную запись');if((v.active===false||v.role==='employee')&&target.role==='admin'){const n=await env.DB.prepare("SELECT COUNT(*) AS n FROM users WHERE role='admin' AND active=1").first();if(Number(n?.n||0)<=1)return err('Нельзя отключить последнего администратора')}if(v.password!==undefined){const pw=String(v.password);if(pw.length<12||pw.length>128)return err('Пароль должен быть от 12 до 128 символов');const salt=uid();await env.DB.prepare('UPDATE users SET password_hash=?,password_salt=? WHERE id=?').bind(await passwordHash(pw,salt),salt,p[2]).run();await env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(p[2]).run()}if(v.active!==undefined||v.role!==undefined||v.displayName!==undefined)await env.DB.prepare('UPDATE users SET active=COALESCE(?,active),role=COALESCE(?,role),display_name=COALESCE(?,display_name) WHERE id=?').bind(v.active===undefined?null:(v.active?1:0),v.role===undefined?null:(v.role==='admin'?'admin':'employee'),v.displayName===undefined?null:trim(v.displayName,80),p[2]).run();return json({ok:true})}return err('Not found',404)}
if(m==='GET'&&p[0]==='data'){const[o,n]=await Promise.all([env.DB.prepare('SELECT id,name,type,lat,lng,created_at AS createdAt,created_by AS createdBy FROM objects ORDER BY created_at DESC').all(),env.DB.prepare('SELECT id,object_id AS objectId,cat,sev,text,author,uid,ts,confirmed,confirms,resolved,has_photo AS hasPhoto FROM notes ORDER BY ts DESC').all()]);return json({objects:o.results,notes:n.results.map(x=>({...x,resolved:!!x.resolved,hasPhoto:!!x.hasPhoto}))})}
if(m==='GET'&&p[0]==='photos'&&p.length===3){const r=await env.DB.prepare('SELECT data FROM photos WHERE object_id=? AND note_id=?').bind(p[1],p[2]).first();return json({data:r?.data||''})}
if(m==='POST'&&p[0]==='objects'&&p.length===1){const v=await req.json(),name=trim(v.name,120),type=trim(v.type,80),lat=Number(v.lat),lng=Number(v.lng);if(!name||!type||!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)return err('Проверьте название и координаты');const id=uid();await env.DB.prepare('INSERT INTO objects(id,name,type,lat,lng,created_at,created_by) VALUES(?,?,?,?,?,?,?)').bind(id,name,type,lat,lng,Date.now(),user.id).run();return json({id})}
if(m==='PUT'&&p[0]==='objects'&&p[1]){const v=await req.json(),own=await env.DB.prepare('SELECT created_by FROM objects WHERE id=?').bind(p[1]).first();if(!own)return err('Объект не найден',404);if(!admin(user)&&own.created_by!==user.id)return err('Недостаточно прав',403);const lat=Number(v.lat),lng=Number(v.lng),name=trim(v.name,120),type=trim(v.type,80);if(!name||!type||!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)return err('Проверьте название и координаты');await env.DB.prepare('UPDATE objects SET name=?,type=?,lat=?,lng=? WHERE id=?').bind(name,type,lat,lng,p[1]).run();return json({ok:true})}
if(m==='DELETE'&&p[0]==='objects'&&p[1]){const own=await env.DB.prepare('SELECT created_by FROM objects WHERE id=?').bind(p[1]).first();if(!own)return err('Объект не найден',404);if(!admin(user)&&own.created_by!==user.id)return err('Недостаточно прав',403);await env.DB.batch([env.DB.prepare('DELETE FROM photos WHERE object_id=?').bind(p[1]),env.DB.prepare('DELETE FROM notes WHERE object_id=?').bind(p[1]),env.DB.prepare('DELETE FROM objects WHERE id=?').bind(p[1])]);return json({ok:true})}
if(m==='POST'&&p[0]==='objects'&&p[2]==='notes'){const v=await req.json(),obj=await env.DB.prepare('SELECT id FROM objects WHERE id=?').bind(p[1]).first();if(!obj)return err('Объект не найден',404);const cat=['road','animals','structure','electric','access','other'].includes(v.cat)?v.cat:'other',sev=Math.max(1,Math.min(3,Number(v.sev)||1)),text=trim(v.text,4000);if(!text)return err('Введите описание');const nid=uid(),photo=String(v.photo||'');await env.DB.prepare('INSERT INTO notes(id,object_id,cat,sev,text,author,uid,ts,confirmed,confirms,resolved,has_photo) VALUES(?,?,?,?,?,?,?,?,0,0,0,?)').bind(nid,p[1],cat,sev,text,trim(v.author||user.displayName,60),user.id,Date.now(),photo?1:0).run();if(photo)await env.DB.prepare('INSERT INTO photos(note_id,object_id,data) VALUES(?,?,?)').bind(nid,p[1],photo).run();return json({id:nid})}
if(m==='POST'&&p[0]==='notes'&&p[2]==='confirm'){await env.DB.prepare('UPDATE notes SET confirmed=?,confirms=confirms+1 WHERE id=?').bind(Date.now(),p[1]).run();return json({ok:true})}
if(m==='POST'&&p[0]==='notes'&&p[2]==='resolve'){if(!admin(user))return err('Закрывать замечания может администратор',403);const v=await req.json();await env.DB.prepare('UPDATE notes SET resolved=?,resolved_at=?,confirmed=? WHERE id=?').bind(v.resolved?1:0,Date.now(),Date.now(),p[1]).run();return json({ok:true})}
return err('Not found',404)}
export default {async fetch(req,env,ctx){const url=new URL(req.url);if(url.pathname.startsWith('/api/')){try{return await api(req,env)}catch(e){console.error(e);return json({error:'Внутренняя ошибка сервера'},500)}}return env.ASSETS.fetch(req)}};